import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { Container, Row, Col, Card, Spinner } from 'react-bootstrap';

const MyEvents = () => {
  const [myEvents, setMyEvents] = useState([]);
  const [loading, setLoading] = useState(true);

  const fetchMyEvents = async () => {
    const token = localStorage.getItem('authToken'); // Retrieve the auth token from localStorage
    console.log("🔹 Token retrieved from localStorage:", token);  // Debugging log

    if (!token) {
      console.error("❌ No auth token found. Redirecting to login.");
      return;
    }

    const config = {
      headers: {
        Authorization: `Bearer ${token}`, // Set token in Authorization header
      },
    };

    try {
      const response = await axios.get('http://localhost:8000/api/events/myevents', config);
      setMyEvents(response.data);  // Update state with user's events
    } catch (error) {
      console.error('❌ Error fetching my events:', error.response?.data || error.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchMyEvents();  // Fetch events for the logged-in user
  }, []);

  return (
    <Container className="mt-4">
      <h2 className="text-center mb-4">My Events</h2>
      {loading ? (
        <div className="text-center">
          <Spinner animation="border" variant="info" />
        </div>
      ) : myEvents.length > 0 ? (
        <Row>
          {myEvents.map((event) => (
            <Col key={event._id} md={4} className="mb-4">
              <Card className="event-card">
                <Card.Img variant="top" src={event.image || 'https://via.placeholder.com/300'} alt={event.title} />
                <Card.Body>
                  <Card.Title>{event.title}</Card.Title>
                  <Card.Text>{event.description}</Card.Text>
                  <Card.Text>{new Date(event.date).toLocaleDateString()}</Card.Text>
                </Card.Body>
              </Card>
            </Col>
          ))}
        </Row>
      ) : (
        <p className="text-center">No events available at the moment.</p>
      )}
    </Container>
  );
};

export default MyEvents;
